      en: ["Built in 1702 by King Bhupatindra Malla.", "It survived both the 1934 and 2015 massive earthquakes."],
      de: ["Erbaut 1702 von König Bhupatindra Malla.", "Es überstand sowohl die schweren Erdbeben von 1934 als auch von 2015."],
      hu: ["1702-ben építtette Bhupatindra Malla király.", "Túlélte az 1934-es és a 2015-ös hatalmas földrengéseket is."],
      ro: ["Construit în 1702 de Regele Bhupatindra Malla.", "A supraviețuit atât cutremurelor masive din 1934, cât și celor din 2015."],
      es: ["Construido en 1702 por el rey Bhupatindra Malla.", "Sobrevivió a los graves terremotos de 1934 y 2015."],
      pt: ["Construído em 1702 pelo rei Bhupatindra Malla.", "Sobreviveu aos graves terremotos de 1934 e 2015."],
      fr: ["Construit en 1702 par le roi Bhupatindra Malla.", "Il a survécu aux graves tremblements de terre de 1934 et de 2015."],
