    image: "/poi-images/np-tansen-durbar-history-v2.webp",
    descriptionAdvanced: {
      de: "Der Tansen Durbar in Palpa war einst der Verwaltungssitz der Rana-Gouverneure und ist ein bedeutendes historisches Wahrzeichen Westnepals. Das ursprüngliche Gebäude wurde im Jahr 1927 von Pratap Shamsher Jang Bahadur Rana erbaut und war bekannt für seine prächtige Architektur mit über 60 Räumen. Der Palast diente jahrzehntelang als Zentrum der regionalen Macht, bis er im Jahr 2006 während des nepalesischen Bürgerkriegs bei einem Angriff fast vollständig zerstört wurde. Nach dem Konflikt wurde der Durbar mit großem Aufwand in seiner ursprünglichen Form rekonstruiert, um das kulturelle Erbe der Region zu bewahren. Heute beherbergt das Gebäude ein Museum, das die Geschichte von Palpa und die Herrschaft der Ranas dokumentiert. Die Architektur des Palastes spiegelt den neoklassizistischen Stil wider, der während der Rana-Ära in Nepal populär war.",
      hu: "A palpai Tansen Durbar egykor a Rana-kormányzók közigazgatási központja volt, és Nyugat-Nepál egyik legfontosabb történelmi emléke. Az eredeti palotát 1927-ben építtette Pratap Shamsher Jang Bahadur Rana, és az épület több mint 60 szobájával a régió hatalmi központjaként szolgált. A palota híres volt masszív falaiairól és díszes kapujáról, amelyet Muldhoka néven ismernek. Sajnos 2006-ban, a nepáli polgárháború idején egy maoista támadás során az épület szinte teljesen leégett és romba dőlt. A konfliktus után a nepáli kormány nagy erőfeszítések árán újjáépítette a palotát az eredeti tervek alapján, hogy megőrizze Palpa történelmi örökségét. Ma az épületben egy múzeum működik, amely bemutatja a térség kulturális kincseit és a Rana-dinasztia korszakát.",
      ro: "Tansen Durbar din Palpa a fost odinioară sediul administrativ al guvernatorilor Rana și este un punct de referință istoric major în vestul Nepalului. Palatul original a fost construit în anul 1927 de către Pratap Shamsher Jang Bahadur Rana, având peste 60 de camere și o structură impunătoare. Timp de decenii, acesta a servit drept centru al puterii regionale, fiind faimos pentru arhitectura sa neoclasică adaptată contextului local. Din păcate, în anul 2006, în timpul războiului civil din Nepal, palatul a fost aproape complet distrus în urma unui atac. După încheierea conflictului, clădirea a fost reconstruită cu fidelitate pentru a reda orașului Tansen identitatea sa istorică. În prezent, edificiul găzduiește un muzeu care expune artefacte istorice și oferă detalii despre dominația dinastiei Rana în regiune.",
      en: "Tansen Durbar in Palpa was once the administrative headquarters of the Rana governors and remains a major historical landmark in western Nepal. The original palace was built in 1927 by Pratap Shamsher Jang Bahadur Rana and was renowned for its grand architecture featuring over 60 rooms. For decades, it served as the center of regional political power until it was almost entirely destroyed during a Maoist insurgent attack in 2006. Following the end of the civil war, the Durbar was meticulously reconstructed to its original design to preserve the cultural heritage of the area. Today, the building houses a museum that documents the history of Palpa and the legacy of the Rana rule. The palace's architecture is a fine example of the neoclassical style that was prevalent in Nepal during the early 20th century.",
      es: "El Tansen Durbar, también conocido como Palpa Durbar, es un palacio histórico en Tansen, Nepal, a unos 200 km al oeste de Katmandú. Fue construido en el siglo XIX por los reyes Sen, que gobernaban el principado de Palpa. El palacio es un ejemplo de arquitectura nepalí con influencias de los estilos Newar y Rajput. El complejo incluye un patio interior, un templo y una terraza con vistas a las cumbres del Himalaya. El palacio servía como sede administrativa y residencia. Tras la anexión de Palpa por el Reino de Nepal en el siglo XIX, el palacio decayó gradualmente. Hoy es un museo y una atracción turística. El terremoto de 2015 causó daños menores. El palacio es un testimonio de la historia de la dinastía Sen.",
      pt: "O Tansen Durbar, também conhecido como Palpa Durbar, é um palácio histórico em Tansen, Nepal, a cerca de 200 km a oeste de Catmandu. Foi construído no século XIX pelos reis Sen, que governavam o principado de Palpa. O palácio é um exemplo da arquitetura nepalesa com influências dos estilos Newar e Rajput. O complexo inclui um pátio interno, um templo e um terraço com vista para os picos dos Himalaias. O palácio servia como sede administrativa e residência. Após a anexação de Palpa pelo Reino do Nepal no século XIX, o palácio entrou gradualmente em decadência. Hoje é um museu e uma atração turística. O terremoto de 2015 causou danos ligeiros. O palácio é um testemunho da história da dinastia Sen.",
      fr: "Le Tansen Durbar, également connu sous le nom de Palpa Durbar, est un palais historique situé à Tansen, au Népal, à environ 200 km à l'ouest de Katmandou. Il a été construit au XIXe siècle par les rois Sen, qui régnaient sur la principauté de Palpa. Le palais est un exemple d'architecture népalaise aux influences des styles Newar et Rajput. Le complexe comprend une cour intérieure, un temple et une terrasse offrant une vue sur les sommets de l'Himalaya. Le palais servait de siège administratif et de résidence. Après l'annexion de Palpa par le royaume du Népal au XIXe siècle, le palais est tombé progressivement en ruine. Aujourd'hui, il abrite un musée et constitue une attraction touristique. Le séisme de 2015 a causé des dommages mineurs. Le palais témoigne de l'histoire de la dynastie Sen.",
    },
