      hu: ["Az eredeti palota 1927-ben épült fel.", "Pratap Shamsher Jang Bahadur Rana építtette.", "Az épületben eredetileg több mint 60 helyiség volt.", "2006-ban a polgárháború alatt súlyosan megrongálódott.", "Az újjáépítés során az eredeti stílust követték.", "Jelenleg Palpa történeti múzeuma működik benne."],
      ro: ["Palatul original a fost finalizat în anul 1927.", "A fost construit de Pratap Shamsher Jang Bahadur Rana.", "Clădirea avea inițial peste 60 de camere administrative.", "A fost distrus aproape complet în ianuarie 2006.", "Reconstrucția a început la scurt timp după conflict.", "Găzduiește acum Muzeul Tansen din districtul Palpa."],
      en: ["The original palace was constructed in 1927.", "It was commissioned by Pratap Shamsher Jang Bahadur Rana.", "The structure originally contained more than 60 rooms.", "The building was destroyed during the civil war in 2006.", "It has since been fully restored to its original glory.", "The palace currently serves as the Palpa District Museum."],
      es: ["Construido en el siglo XIX", "A 200 km al oeste de Katmandú", "Dinastía Sen", "Estilo Newar y Rajput", "Daños menores en 2015", "Hoy es un museo"],
      pt: ["Construído no século XIX", "A 200 km a oeste de Catmandu", "Dinastia Sen", "Estilos Newar e Rajput", "Danos ligeiros em 2015", "Museu atualmente"],
      fr: ["Construit au XIXe siècle", "À 200 km à l'ouest de Katmandou", "Dynastie Sen", "Styles Newar et Rajput", "Dommages mineurs en 2015", "Musée aujourd'hui"],
